  'm.srcCoverage': {
    en: '<b>Coverage.</b> All <b class="num">{covered}</b> cantons deliver this model to geodienste.ch and all {free} publish it freely. The delivery dates run from <b class="num">{oldest}</b> ({ct}, {yrs} years ago) to <b class="num">{newest}</b>, so the national picture is as old as {ct}, not as new as its newest canton. Liechtenstein, which shares the service, delivers nothing here.',
    de: '<b>Abdeckung.</b> Alle <b class="num">{covered}</b> Kantone liefern dieses Modell an geodienste.ch und alle {free} publizieren es frei. Die Lieferdaten reichen von <b class="num">{oldest}</b> ({ct}, vor {yrs} Jahren) bis <b class="num">{newest}</b>; das nationale Bild ist damit so alt wie {ct} und nicht so neu wie sein neuester Kanton. Liechtenstein, das den Dienst mitbenutzt, liefert hier nichts.',
    fr: '<b>Couverture.</b> Les <b class="num">{covered}</b> cantons livrent tous ce modèle à geodienste.ch et tous les {free} le publient librement. Les dates de livraison vont du <b class="num">{oldest}</b> ({ct}, il y a {yrs} ans) au <b class="num">{newest}</b> : l’image nationale est donc aussi ancienne que {ct}, et non aussi récente que son canton le plus récent. Le Liechtenstein, qui partage le service, ne livre rien ici.',
    it: '<b>Copertura.</b> Tutti i <b class="num">{covered}</b> cantoni consegnano questo modello a geodienste.ch e tutti i {free} lo pubblicano liberamente. Le date di consegna vanno dal <b class="num">{oldest}</b> ({ct}, {yrs} anni fa) al <b class="num">{newest}</b>: l’immagine nazionale è quindi vecchia quanto {ct}, non nuova quanto il suo cantone più recente. Il Liechtenstein, che condivide il servizio, qui non consegna nulla.',
    rm: '<b>Cuvrida.</b> Tut ils <b class="num">{covered}</b> chantuns furneschan quest model a geodienste.ch e tut ils {free} al publitgeschan liberamain. Las datas da furniziun van dals <b class="num">{oldest}</b> ({ct}, avant {yrs} onns) als <b class="num">{newest}</b>: il maletg naziunal è pia uschè vegl sco {ct} e betg uschè nov sco ses chantun il pli nov. Il Liechtenstein, che dovra il medem servetsch, na furnescha nagut qua.',
  },

